<script setup lang="ts">
import { onMounted,onBeforeUnmount,ref,nextTick } from 'vue';
import { useAdminStore } from '../../stores/admin';
import type { AdminUser,AdminSubmission } from '../../contracts/admin';
import { adminSubmissionKinds,adminSubmissionLabels } from '../../contracts/admin';
import UiButton from '../../components/UiButton.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import StatusSlot from '../../components/StatusSlot.vue';
const admin=useAdminStore(),confirm=ref<InstanceType<typeof ConfirmDialog>|null>(null),secretHeading=ref<HTMLElement|null>(null);
async function showSecret(){await nextTick();secretHeading.value?.focus({preventScroll:true});secretHeading.value?.scrollIntoView({block:'nearest',behavior:'auto'});}
function expires(value:string){return new Date(value).toLocaleString('zh-TW',{hour12:false});}
async function invite(){if(admin.uncertain==='invite'&&!await confirm.value?.ask('上次產生邀請碼的結果尚未確認；重新產生會建立另一張有效邀請碼。確定要產生新的邀請碼？','產生新的邀請碼'))return;if(await admin.invite())await showSecret();}
async function revoke(){const code=admin.revokeCode.trim();if(!code)return;if(await confirm.value?.ask('撤銷輸入的未使用邀請碼？撤銷後不能再用於註冊。','撤銷邀請碼'))await admin.revoke();}
async function reset(user:AdminUser){if(await confirm.value?.ask(`為「${user.displayName}（${user.username}）」產生密碼重設連結？請只交給這位會員，連結使用後會登出其既有登入。${admin.uncertain==='reset:'+user.id?' 上次操作結果未確認，再產生會建立另一個有效連結。':''}`,'產生重設連結'))if(await admin.reset(user))await showSecret();}
async function toggle(user:AdminUser){if(await confirm.value?.ask(user.disabled?`重新啟用「${user.displayName}（${user.username}）」？`:`停用「${user.displayName}（${user.username}）」？該帳號現有登入會失效。`,user.disabled?'啟用會員':'停用會員'))await admin.setDisabled(user);}
async function retry(item:AdminSubmission){if(await confirm.value?.ask(`已在 GitHub 確認提交 ${item.id} 沒有對應 Issue、回覆或狀態變更？只有確認沒有建立後才重試；此操作可能對外寫入 GitHub，並可能建立重複內容。`,'已查核，確認重試'))await admin.retry(item);}
onMounted(()=>{void admin.refreshAccess();});
onBeforeUnmount(()=>{confirm.value?.cancel();admin.clearSecret();});
</script>
<template><div class="page-heading"><div class="kicker">THE CLUB / CONTROL ROOM</div><h1>管理者工具</h1><p>管理會員與邀請，確認留言板的 GitHub 同步狀態。</p></div>
 <div class="vue-admin-access"><a class="vue-admin-link-button" href="/market#admin">股市冥燈：建立交易日與結算 ↗</a><UiButton icon="refresh" label="重新確認管理權限與清單" :pending="admin.usersLoading || admin.submissionsLoading" :disabled="admin.pending" @click="admin.refreshAccess()" /></div>
 <StatusSlot v-if="admin.forbidden" message="只有管理者可以操作此頁。請使用具有管理權限的帳號。" error />
 <div class="admin-grid vue-admin-grid">
  <section class="page-panel invite-panel" aria-labelledby="admin-invite-heading"><header class="panel-heading"><h2 id="admin-invite-heading">邀請與一次性連結</h2><p>邀請碼與密碼重設連結只在產生當下顯示；請安全交給對方。此頁不保存到瀏覽器儲存空間。</p></header>
   <form id="inviteForm" class="vue-admin-inline-form" autocomplete="off" @submit.prevent="invite"><label for="admin-invite-days">邀請碼有效天數<input id="admin-invite-days" v-model.number="admin.days" name="days" type="number" min="1" max="90" required :disabled="!admin.canWrite"></label><UiButton type="submit" icon="add" label="產生邀請碼" :pending="admin.operation==='invite'" :disabled="!admin.canWrite" /></form>
   <form id="revokeForm" class="vue-admin-inline-form" autocomplete="off" @submit.prevent="revoke"><label for="admin-revoke-code">撤銷未使用的邀請碼<input id="admin-revoke-code" v-model="admin.revokeCode" name="code" placeholder="貼上邀請碼" autocomplete="off" autocapitalize="off" spellcheck="false" required :disabled="!admin.canWrite"></label><UiButton type="submit" icon="remove" label="撤銷邀請碼" :pending="admin.operation==='revoke'" :disabled="!admin.canWrite || !admin.revokeCode.trim()" /></form>
   <StatusSlot id="admin-invite-status" :message="admin.invitationMessage" :error="admin.invitationFailed" />
   <section class="vue-admin-secret-slot" aria-labelledby="admin-secret-heading"><div class="vue-admin-secret-heading"><h3 id="admin-secret-heading" ref="secretHeading" tabindex="-1">一次性連結</h3><UiButton v-if="admin.secret" icon="close" label="清除畫面上的連結" @click="admin.clearSecret()" /></div><div v-if="admin.secret" class="vue-admin-secret"><p>{{ admin.secret.kind==='invite'?'註冊邀請碼':'密碼重設連結' }}<span v-if="admin.secret.recipient"> · {{ admin.secret.recipient }}</span></p><label v-if="admin.secret.kind==='invite'">邀請碼<input :value="admin.secret.value" readonly autocomplete="off" spellcheck="false" @focus="($event.target as HTMLInputElement).select()"></label><p>期限：{{ expires(admin.secret.expiresAt) }}</p><label>連結<input :value="admin.secret.href" readonly autocomplete="off" spellcheck="false" @focus="($event.target as HTMLInputElement).select()"></label><div id="inviteLinkActions" class="vue-admin-actions"><a id="inviteLink" class="vue-admin-link-button" :href="admin.secret.href" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">開啟{{ admin.secret.kind==='invite'?'邀請':'重設' }}連結 ↗</a><UiButton id="copyInviteLink" icon="copy" label="複製連結" @click="admin.copySecret()" /></div><StatusSlot :message="admin.copyMessage" /></div><p v-else>產生邀請碼或會員重設連結後會顯示在這裡。離開頁面或清除後無法再次查閱。</p></section>
  </section>
  <section class="page-panel sync-panel" aria-labelledby="admin-sync-heading"><header class="panel-heading"><h2 id="admin-sync-heading">待確認提交</h2><p>結果不明時，請先到 GitHub 查核；確認沒有建立後才能重試。</p></header><UiButton id="refreshSubmissions" icon="refresh" label="更新提交清單" :pending="admin.submissionsLoading" :disabled="admin.pending || admin.forbidden" @click="admin.loadSubmissions()" /><StatusSlot :message="admin.submissionsError || (admin.submissionsLoading?'正在讀取提交清單…':'')" :error="!!admin.submissionsError" /><StatusSlot id="admin-sync-status" :message="admin.syncMessage" :error="admin.syncFailed" />
   <div id="submissions" class="vue-admin-submission-list" tabindex="0" aria-label="待處理提交，可捲動查看" :aria-busy="admin.submissionsLoading"><article v-for="item in admin.submissions" :key="item.id"><div><strong>{{ adminSubmissionKinds[item.kind] }}</strong><span>{{ adminSubmissionLabels[item.state] }}</span></div><code>{{ item.id }}</code><p>{{ expires(item.createdAt) }}</p><p v-if="item.error" class="vue-admin-submission-error">{{ item.error }}</p><UiButton v-if="item.state==='needs_review'" icon="refresh" label="已查核 GitHub，確認後重試" :pending="admin.operation==='retry:'+item.id" :disabled="!admin.canWrite || admin.submissionsLoading" @click="retry(item)" /></article><p v-if="admin.submissionsLoaded && !admin.submissionsLoading && !admin.submissionsError && !admin.submissions.length">目前沒有待處理提交。</p></div>
  </section>
 </div>
 <section class="page-panel members-panel" aria-labelledby="admin-members-heading"><header class="vue-admin-members-heading"><div><h2 id="admin-members-heading">會員名單</h2><p>可建立密碼重設連結，或停用與重新啟用會員。管理者帳號不能在此停用。</p></div><UiButton icon="refresh" label="更新會員名單" :pending="admin.usersLoading" :disabled="admin.pending || admin.forbidden" @click="admin.loadUsers()" /></header><StatusSlot :message="admin.usersError || (admin.usersLoading?'正在讀取會員名單…':'')" :error="!!admin.usersError" /><StatusSlot id="admin-member-status" :message="admin.memberMessage" :error="admin.memberFailed" /><p v-if="admin.uncertain" class="vue-admin-uncertain" role="status">上一筆操作結果尚未確認，請先確認目前狀態。此頁不會自動重送操作；GitHub 同步須另外到 GitHub 查核。</p>
  <div class="vue-admin-table-scroll" tabindex="0" aria-label="會員名單，可捲動查看" :aria-busy="admin.usersLoading"><table><thead><tr><th scope="col">帳號</th><th scope="col">暱稱</th><th scope="col">狀態</th><th scope="col">操作</th></tr></thead><tbody id="users"><tr v-for="user in admin.users" :key="user.id"><td>{{ user.username }}</td><td>{{ user.displayName }}</td><td>{{ user.disabled?'已停用':'正常' }}{{ user.role==='admin'?' · 管理者':'' }}</td><td><div class="vue-admin-actions"><UiButton icon="lock" :label="'為 '+user.username+' 建立密碼重設連結'" caption="重設密碼" :pending="admin.operation==='reset:'+user.id" :disabled="!admin.canWrite || admin.usersLoading" @click="reset(user)" /><UiButton v-if="user.role!=='admin'" :icon="user.disabled?'check':'close'" :label="(user.disabled?'啟用 ':'停用 ')+user.username" :caption="user.disabled?'啟用會員':'停用會員'" :pending="admin.operation==='disable:'+user.id" :disabled="!admin.canWrite || admin.usersLoading" @click="toggle(user)" /></div></td></tr><tr v-if="admin.usersLoaded && !admin.usersLoading && !admin.users.length"><td colspan="4">目前沒有會員資料。</td></tr></tbody></table></div>
 </section><ConfirmDialog ref="confirm" />
</template>
